  2→
  3→/**
  4→ * Contract: Declares the encryption mechanism for a field. Each variant maps 1:1 to an
  5→ * encryption family and exposes capability methods that the {@link jlsm.table.internal.IndexRegistry}
  6→ * uses to validate index compatibility at schema construction time.
  7→ *
  8→ * <p>Governed by: .decisions/field-encryption-api-design/adr.md
  9→ */
 10→public sealed interface EncryptionSpec
 11→        permits EncryptionSpec.None,
 12→                EncryptionSpec.Deterministic,
 13→                EncryptionSpec.OrderPreserving,
 14→                EncryptionSpec.DistancePreserving,
 15→                EncryptionSpec.Opaque {
 16→
 17→    /** The singleton no-encryption specification. */
 18→    EncryptionSpec NONE = new None();
 19→
 20→    // ── Capability query methods ──────────────────────────────────────────────
 21→
 22→    /** Returns {@code true} if equality comparisons are supported on encrypted values. */
 23→    default boolean supportsEquality() { return false; }
 24→
 25→    /** Returns {@code true} if range (ordering) queries are supported on encrypted values. */
 26→    default boolean supportsRange() { return false; }
 27→
 28→    /** Returns {@code true} if keyword (single-term) search is supported on encrypted values. */
 29→    default boolean supportsKeywordSearch() { return false; }
 30→
 31→    /** Returns {@code true} if phrase / proximity search is supported on encrypted values. */
 32→    default boolean supportsPhraseSearch() { return false; }
 33→
 34→    /** Returns {@code true} if SSE-based encrypted index search is supported. */
 35→    default boolean supportsSseSearch() { return false; }
 36→
 37→    /** Returns {@code true} if approximate nearest-neighbor search is supported on encrypted values. */
 38→    default boolean supportsANN() { return false; }
 39→
 40→    // ── Permits ───────────────────────────────────────────────────────────────
 41→
 42→    /**
 43→     * No encryption — field values are stored in plaintext.
 44→     * All capabilities are trivially supported (delegated to the underlying index).
 45→     */
 46→    record None() implements EncryptionSpec {
 47→        @Override public boolean supportsEquality()      { return true; }
 48→        @Override public boolean supportsRange()          { return true; }
 49→        @Override public boolean supportsKeywordSearch()  { return true; }
 50→        @Override public boolean supportsPhraseSearch()   { return true; }
 51→        @Override public boolean supportsSseSearch()      { return true; }
 52→        @Override public boolean supportsANN()            { return true; }
 53→    }
 54→
 55→    /**
 56→     * Deterministic encryption (AES-SIV). Same plaintext always produces the same ciphertext
 57→     * under the same key, enabling equality comparisons and keyword search via inverted index.
 58→     */
 59→    record Deterministic() implements EncryptionSpec {
 60→        @Override public boolean supportsEquality()      { return true; }
 61→        @Override public boolean supportsKeywordSearch()  { return true; }
 62→    }
 63→
 64→    /**
 65→     * Order-preserving encryption (Boldyreva OPE). Ciphertext ordering matches plaintext
 66→     * ordering, enabling range queries. Also supports equality.
 67→     */
 68→    record OrderPreserving() implements EncryptionSpec {
 69→        @Override public boolean supportsEquality() { return true; }
 70→        @Override public boolean supportsRange()    { return true; }
 71→    }
 72→
 73→    /**
 74→     * Distance-comparison-preserving encryption (DCPE / Scale-And-Perturb). Encrypted vectors
 75→     * approximate the distance relationships of plaintext vectors, enabling ANN search.
 76→     */
 77→    record DistancePreserving() implements EncryptionSpec {
 78→        @Override public boolean supportsANN() { return true; }
 79→    }
 80→
 81→    /**
 82→     * Opaque encryption (AES-GCM). No search capability — values must be decrypted before
 83→     * any comparison. Provides the strongest security guarantee.
 84→     */
 85→    record Opaque() implements EncryptionSpec {
 86→        // All capabilities default to false
 87→    }
 88→
 89→    // ── Static factory methods ────────────────────────────────────────────────
 90→
 91→    /** Returns the no-encryption specification. */
 92→    static EncryptionSpec none() { return NONE; }
 93→
 94→    /** Returns a deterministic encryption specification (AES-SIV). */
 95→    static EncryptionSpec deterministic() { return new Deterministic(); }
 96→
 97→    /** Returns an order-preserving encryption specification (Boldyreva OPE). */
 98→    static EncryptionSpec orderPreserving() { return new OrderPreserving(); }
 99→
100→    /** Returns a distance-preserving encryption specification (DCPE / SAP). */
101→    static EncryptionSpec distancePreserving() { return new DistancePreserving(); }
102→
103→    /** Returns an opaque encryption specification (AES-GCM). */
104→    static EncryptionSpec opaque() { return new Opaque(); }
105→}
