                case EncryptionSpec.None _ -> "none";
                case EncryptionSpec.Deterministic _ -> "deterministic";
                case EncryptionSpec.OrderPreserving _ -> "orderPreserving";
                case EncryptionSpec.DistancePreserving _ -> "distancePreserving";
